import json, sys


import re

FORBIDDEN = ['\\bwrite\\b', '\\breload\\b', '\\bconfigure\\s+replace\\b', '\\barchive\\b', '\\bcrypto\\s+key\\b', '\\busername\\b', '\\benable\\s+secret\\b', '\\bcopy\\b', '\\bdelete\\b', '\\berase\\b', '\\bformat\\b', '\\bboot\\b', '\\blicense\\b', '\\bevent\\s+manager\\b', '\\btclsh\\b', '^\\s*do\\s', '\\bmgmt\\b', '\\bg(?:i(?:g(?:a(?:b(?:i(?:t(?:e(?:t(?:h(?:e(?:r(?:n(?:e(?:t)?)?)?)?)?)?)?)?)?)?)?)?)?)?\\s*0*1(?![0-9/])', '\\bnetconf']
COMMANDS = [['write'], ['reload'], ['configure', 'replace'], ['archive'], ['crypto', 'key'], ['username'], ['enable', 'secret'], ['enable', 'password'], ['privilege'], ['copy'], ['delete'], ['erase'], ['format'], ['boot'], ['license'], ['event', 'manager'], ['kron'], ['tclsh'], ['do'], ['end'], ['exit'], ['alias'], ['line'], ['aaa'], ['login'], ['restconf'], ['ip', 'http'], ['ip', 'ssh'], ['crypto', 'pki'], ['crypto', 'ca'], ['control-plane'], ['ip', 'routing']]


def scratch_push_plan(d: dict, forbidden: list, commands: list) -> dict:
    """Every proposed line against the forbidden set before any card exists: a pattern anywhere in the line
    (case-insensitive), or a forbidden command at its start as IOS XE reads it - each word abbreviated to any prefix,
    read both as written and with a leading `no` or `default` (to any prefix: `defa` is `default`, while `d` and `de`
    can still be `do` and `delete`) set aside. When none is refused, the lines joined for send-config and the card's body.
    Pure: runCode runs this function's own source on the Gateway."""
    lines = d.get("lines")
    if not isinstance(lines, list) or not lines or not all(isinstance(x, str) for x in lines):
        return {"ok": False, "refused": [], "message": "the lines are not a list of strings: nothing was sent"}
    patterns = [re.compile(p, re.IGNORECASE) for p in forbidden]

    def is_command(line: str) -> bool:
        words = line.lower().split()
        while words:
            if any(len(words) >= len(cmd) and all(c.startswith(w) for w, c in zip(words, cmd)) for cmd in commands):
                return True
            if words[0] != "no" and not "default".startswith(words[0]):
                return False
            words = words[1:]
        return False

    refused = [x for x in lines if any(p.search(x) for p in patterns) or is_command(x)]
    if refused:
        return {"ok": False, "refused": refused,
                "message": "refused before any approval, forbidden on the scratch routers: " + "; ".join(refused)
                           + ". Nothing was sent to the router"}
    return {"ok": True, "refused": [], "config": "\n".join(lines),
            "card": {"device": d.get("device"), "reason": d.get("reason") or "", "lines": lines}}


print(json.dumps(scratch_push_plan(json.loads(sys.stdin.read() or "{}"), FORBIDDEN, COMMANDS)))
